create extension if not exists pgcrypto;
create schema if not exists private;
create table if not exists public.tenants(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,plan text not null default 'enterprise',status text not null default 'active',created_at timestamptz not null default now());
create table if not exists public.tenant_memberships(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null,created_at timestamptz not null default now(),unique(tenant_id,user_id));
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,legal_name text not null,trade_name text not null,cnpj text not null,city text not null,state char(2) not null,created_at timestamptz not null default now(),unique(tenant_id,cnpj));
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,name text not null,document text not null,email text,phone text,status text not null default 'active',created_at timestamptz not null default now(),unique(tenant_id,document));
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,name text not null,document text not null,email text,lead_time_days integer not null default 7,status text not null default 'active',created_at timestamptz not null default now(),unique(tenant_id,document));
create table if not exists public.products(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,sku text not null,name text not null,category text not null,price_cents bigint not null default 0,cost_cents bigint not null default 0,status text not null default 'active',created_at timestamptz not null default now(),unique(tenant_id,sku));
create table if not exists public.sales_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,number text not null,customer_name text not null,total_cents bigint not null,status text not null default 'open',created_at timestamptz not null default now(),unique(tenant_id,number));
create table if not exists public.purchase_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,number text not null,supplier_name text not null,total_cents bigint not null,status text not null default 'open',expected_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,number));
create table if not exists public.production_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,number text not null,product_name text not null,planned_qty integer not null,produced_qty integer not null default 0,status text not null default 'planned',due_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,number));
create table if not exists public.receivables(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,description text not null,amount_cents bigint not null,due_at timestamptz not null,status text not null default 'open',created_at timestamptz not null default now());
create table if not exists public.payables(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,description text not null,amount_cents bigint not null,due_at timestamptz not null,status text not null default 'open',created_at timestamptz not null default now());
create table if not exists public.employees(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,registration text not null,name text not null,department text not null,position text not null,status text not null default 'active',hired_at date not null,created_at timestamptz not null default now(),unique(tenant_id,registration));
create table if not exists public.shipments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,code text not null,carrier text not null,destination text not null,status text not null default 'preparing',freight_cents bigint not null default 0,eta timestamptz,created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,actor_id uuid not null references auth.users(id),action text not null,entity text not null,entity_id uuid not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function private.is_tenant_member(requested_tenant uuid) returns boolean language sql security definer set search_path='' stable as $$ select exists(select 1 from public.tenant_memberships tm where tm.tenant_id=requested_tenant and tm.user_id=(select auth.uid())) $$;
revoke execute on function private.is_tenant_member(uuid) from public, anon;
grant usage on schema private to authenticated;
grant execute on function private.is_tenant_member(uuid) to authenticated;
alter table public.tenants enable row level security;alter table public.tenant_memberships enable row level security;alter table public.organizations enable row level security;alter table public.customers enable row level security;alter table public.suppliers enable row level security;alter table public.products enable row level security;alter table public.sales_orders enable row level security;alter table public.purchase_orders enable row level security;alter table public.production_orders enable row level security;alter table public.receivables enable row level security;alter table public.payables enable row level security;alter table public.employees enable row level security;alter table public.shipments enable row level security;alter table public.audit_logs enable row level security;
create policy tenants_select on public.tenants for select to authenticated using(private.is_tenant_member(id));
create policy memberships_select on public.tenant_memberships for select to authenticated using(private.is_tenant_member(tenant_id));
create policy organizations_select on public.organizations for select to authenticated using(private.is_tenant_member(tenant_id));create policy organizations_insert on public.organizations for insert to authenticated with check(private.is_tenant_member(tenant_id));create policy organizations_update on public.organizations for update to authenticated using(private.is_tenant_member(tenant_id)) with check(private.is_tenant_member(tenant_id));
create policy customers_select on public.customers for select to authenticated using(private.is_tenant_member(tenant_id));create policy customers_insert on public.customers for insert to authenticated with check(private.is_tenant_member(tenant_id));create policy customers_update on public.customers for update to authenticated using(private.is_tenant_member(tenant_id)) with check(private.is_tenant_member(tenant_id));
create policy suppliers_select on public.suppliers for select to authenticated using(private.is_tenant_member(tenant_id));create policy suppliers_insert on public.suppliers for insert to authenticated with check(private.is_tenant_member(tenant_id));create policy suppliers_update on public.suppliers for update to authenticated using(private.is_tenant_member(tenant_id)) with check(private.is_tenant_member(tenant_id));
create policy products_select on public.products for select to authenticated using(private.is_tenant_member(tenant_id));create policy products_insert on public.products for insert to authenticated with check(private.is_tenant_member(tenant_id));create policy products_update on public.products for update to authenticated using(private.is_tenant_member(tenant_id)) with check(private.is_tenant_member(tenant_id));
create policy sales_orders_select on public.sales_orders for select to authenticated using(private.is_tenant_member(tenant_id));create policy purchase_orders_select on public.purchase_orders for select to authenticated using(private.is_tenant_member(tenant_id));create policy production_orders_select on public.production_orders for select to authenticated using(private.is_tenant_member(tenant_id));create policy receivables_select on public.receivables for select to authenticated using(private.is_tenant_member(tenant_id));create policy payables_select on public.payables for select to authenticated using(private.is_tenant_member(tenant_id));create policy employees_select on public.employees for select to authenticated using(private.is_tenant_member(tenant_id));create policy shipments_select on public.shipments for select to authenticated using(private.is_tenant_member(tenant_id));create policy audit_select on public.audit_logs for select to authenticated using(private.is_tenant_member(tenant_id));
create index if not exists customers_tenant_status_idx on public.customers(tenant_id,status);create index if not exists suppliers_tenant_status_idx on public.suppliers(tenant_id,status);create index if not exists products_tenant_status_idx on public.products(tenant_id,status);create index if not exists sales_orders_tenant_status_idx on public.sales_orders(tenant_id,status);create index if not exists purchase_orders_tenant_status_idx on public.purchase_orders(tenant_id,status);create index if not exists production_orders_tenant_status_idx on public.production_orders(tenant_id,status);create index if not exists receivables_tenant_due_idx on public.receivables(tenant_id,status,due_at);create index if not exists payables_tenant_due_idx on public.payables(tenant_id,status,due_at);create index if not exists employees_tenant_status_idx on public.employees(tenant_id,status);create index if not exists shipments_tenant_status_idx on public.shipments(tenant_id,status);create index if not exists audit_logs_tenant_created_idx on public.audit_logs(tenant_id,created_at desc);
